import json
from solver import solve_mckp_constrained, enforce_monotonicity
with open('llama_hires_bf16_2bitonly_profiles.json') as f:
    hires_raw = json.load(f)
hires = hires_raw.get('profiles', hires_raw)
with open('llama_profiling_results.json') as f:
    std_raw = json.load(f)
std = std_raw.get('profiles', std_raw)
merged = {}
for l_str in sorted(hires.keys(), key=int):
    merged[l_str] = {}
    for h_str in sorted(hires[l_str].keys(), key=int):
        d2 = hires[l_str][h_str]['quantization']['2']
        q = {'2': d2}
        if l_str in std and h_str in std[l_str]:
            sq = std[l_str][h_str].get('quantization', {})
            for b in ['4', '8']:
                if b in sq:
                    q[b] = sq[b]
        merged[l_str][h_str] = {'quantization': q}
profiles = enforce_monotonicity(merged)

for k in [2, 8]:
    mckp = solve_mckp_constrained(profiles, 0.25, mode='quant_only', max_2bit=k, l0_exclude_2bit=True)
    alloc = mckp['allocation']
    n2 = sum(1 for v in alloc.values() if isinstance(v, list) and v[1] == 2)
    n4 = sum(1 for v in alloc.values() if isinstance(v, list) and v[1] == 4)
    n8 = sum(1 for v in alloc.values() if isinstance(v, list) and v[1] == 8)
    print(f'k={k}: 2bit={n2}, 4bit={n4}, 8bit={n8}, budget={mckp[\"actual_memory_ratio\"]:.4f}, distortion={mckp[\"total_distortion\"]:.6f}')
    print(f'  bit_distribution: {mckp.get(\"bit_distribution\", {})}')
"

